<?php
declare(strict_types=1);
$statusLabels=['draft'=>'Taslak','confirmed'=>'Onaylandı','processing'=>'Hazırlanıyor','shipped'=>'Kargolandı','completed'=>'Tamamlandı','cancelled'=>'İptal'];
$nextActions=['draft'=>['confirmed'=>'Siparişi onayla','cancelled'=>'İptal et'],'confirmed'=>['processing'=>'Hazırlamaya al','cancelled'=>'İptal et'],'processing'=>['shipped'=>'Kargoya ver','cancelled'=>'İptal et'],'shipped'=>['completed'=>'Tamamlandı olarak işaretle']];
?>
<div class="module-toolbar"><div><p class="module-intro">Sipariş detayları, ürün kalemleri ve durum geçmişi.</p></div><a class="btn secondary action-link" href="index.php?page=orders">← Sipariş listesi</a></div>
<section class="panel order-summary"><div><span class="eyebrow">SİPARİŞ NUMARASI</span><h2><?= kd_e($order['order_number']) ?></h2><span class="order-status status-<?= kd_e($order['status']) ?>"><?= kd_e($statusLabels[$order['status']]??$order['status']) ?></span></div><div class="order-summary-meta"><small>Müşteri</small><strong><?= kd_e($order['customer_name']?:'Misafir müşteri') ?></strong><small>Oluşturulma</small><strong><?= kd_e(date('d.m.Y H:i',strtotime((string)$order['created_at']))) ?></strong></div></section>
<div class="customer-detail-grid"><section class="panel"><h3>Ürünler</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Ürün</th><th>Miktar</th><th>Birim fiyat</th><th>KDV</th><th>Toplam</th></tr></thead><tbody><?php foreach($items as $item): ?><tr><td><strong><?= kd_e($item['product_name']) ?></strong><small class="table-sub"><?= kd_e($item['sku']?:'') ?></small></td><td><?= number_format((float)$item['quantity'],3,',','.') ?></td><td><?= number_format((float)$item['unit_price'],2,',','.') ?> ₺</td><td><?= number_format((float)$item['tax_rate'],2,',','.') ?>%</td><td><strong><?= number_format((float)$item['line_total'],2,',','.') ?> ₺</strong></td></tr><?php endforeach; ?></tbody></table></div><div class="order-totals"><div><span>Ara toplam</span><strong><?= number_format((float)$order['subtotal'],2,',','.') ?> ₺</strong></div><div><span>KDV toplamı</span><strong><?= number_format((float)$order['tax_total'],2,',','.') ?> ₺</strong></div><div class="grand-total"><span>Genel toplam</span><strong><?= number_format((float)$order['grand_total'],2,',','.') ?> ₺</strong></div></div><?php if($order['notes']): ?><p class="muted"><?= nl2br(kd_e($order['notes'])) ?></p><?php endif; ?></section>
<section class="panel activity-panel"><h3>Sipariş süreci</h3><?php if(kd_can('orders.manage')&&!empty($nextActions[$order['status']])): ?><form class="activity-form" method="post" action="index.php?page=orders&action=view&id=<?= (int)$order['id'] ?>"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="status"><input type="hidden" name="order_id" value="<?= (int)$order['id'] ?>"><label>Yeni durum<select name="status"><?php foreach($nextActions[$order['status']] as $key=>$label): ?><option value="<?= kd_e($key) ?>"><?= kd_e($label) ?></option><?php endforeach; ?></select></label><label>İşlem notu<input name="note" maxlength="255" placeholder="İsteğe bağlı not"></label><button class="btn primary">Durumu güncelle</button></form><?php endif; ?>
<div class="timeline"><?php foreach($history as $event): ?><article class="timeline-item"><span class="timeline-dot"></span><div><strong><?= kd_e($event['from_status']?($statusLabels[$event['from_status']]??$event['from_status']).' → ':'') ?><?= kd_e($statusLabels[$event['to_status']]??$event['to_status']) ?></strong><?php if($event['note']): ?><p><?= kd_e($event['note']) ?></p><?php endif; ?><small><?= kd_e($event['user_name']?:'Sistem') ?> · <?= kd_e(date('d.m.Y H:i',strtotime((string)$event['created_at']))) ?></small></div></article><?php endforeach; ?></div></section></div>
